using System;
using System.Collections.Generic;

public class VehicleSensorIngester
{
    private Dictionary<string, int> laneQueues;

    public VehicleSensorIngester()
    {
        laneQueues = new Dictionary<string, int>();
    }

    public void UpdateQueue(string lane, int count)
    {
        if (laneQueues.ContainsKey(lane))
        {
            laneQueues[lane] = count;
        }
        else
        {
            laneQueues.Add(lane, count);
        }
    }

    public Dictionary<string, int> GetQueues()
    {
        return new Dictionary<string, int>(laneQueues);  // Create a copy
    }
}

public class AdaptiveTimingOptimizationEngine
{
    private Dictionary<string, int> queues;
    private double greenLightDuration;
    private int maxGreenLightDuration;
    private int minGreenLightDuration;

    public AdaptiveTimingOptimizationEngine(Dictionary<string, int> queues)
    {
        this.queues = queues;
        greenLightDuration = 30;
        maxGreenLightDuration = 60;
        minGreenLightDuration = 10;
    }

    public double Optimize()
    {
        int totalVehicles = 0;
        foreach (var queue in queues)
        {
            totalVehicles += queue.Value;
        }

        if (totalVehicles > 50)
        {
            greenLightDuration = Math.Min(greenLightDuration + 1, maxGreenLightDuration);
        }
        else if (totalVehicles < 5)
        {
            greenLightDuration = Math.Max(greenLightDuration - 1, minGreenLightDuration);
        }

        return greenLightDuration;
    }
}

public class HardwareSignalController
{
    private string currentState;

    public HardwareSignalController()
    {
        currentState = "red";
    }

    public void ChangeState(string newState)
    {
        if (newState == "red" || newState == "green" || newState == "yellow")
        {
            currentState = newState;
            Console.WriteLine($"Traffic light state changed to {newState}");
        }
        else
        {
            Console.WriteLine("Invalid state");
        }
    }

    public void Dispatch(string newState)
    {
        ChangeState(newState);
    }
}

class Program
{
    static void Main()
    {
        var sensorIngester = new VehicleSensorIngester();
        sensorIngester.UpdateQueue("lane1", 10);
        sensorIngester.UpdateQueue("lane2", 20);

        var queues = sensorIngester.GetQueues();

        var optimizationEngine = new AdaptiveTimingOptimizationEngine(queues);
        var greenLightDuration = optimizationEngine.Optimize();

        var signalController = new HardwareSignalController();
        signalController.Dispatch("green");
    }
}
